"use client"

import * as React from "react"
import { ArrowDown, ArrowUp, ChevronsUpDown } from "lucide-react"

import { cn } from "@/lib/utils"

/**
 * The scroll chrome a Nessa scroll region wears: a thin, track-less bar with
 * a rounded hairline thumb that strengthens on hover, rather than the
 * platform default. Applied to the table's scroll port; exported so a host
 * building its own scrolling surface can match it.
 */
const tableScrollbarClassName =
  "[scrollbar-width:thin] [scrollbar-color:var(--color-border)_transparent] [&::-webkit-scrollbar]:size-2 [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar-corner]:bg-transparent [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-border [&::-webkit-scrollbar-thumb]:bg-clip-padding [&::-webkit-scrollbar-thumb]:border-2 [&::-webkit-scrollbar-thumb]:border-transparent [&::-webkit-scrollbar-thumb:hover]:bg-muted-foreground"

/**
 * The flat bordered panel a data table sits on: hairline border, card
 * surface, clipped corners, no elevation. Stack a `Table` and, optionally,
 * a `TablePagination` inside it; toolbars belong outside, above the shell.
 */
function TableShell({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="table-shell"
      className={cn(
        "flex box-border w-full min-w-0 flex-col overflow-hidden rounded-xl border border-border bg-card font-sans text-card-foreground",
        className,
      )}
      {...props}
    />
  )
}

export interface TableProps extends React.ComponentProps<"table"> {
  /**
   * Extends the scroll container that wraps the table — the node to cap
   * with `max-h-*` for a scrolling body, since the table itself is not the
   * scroll port. Pair a sticky `TableHeader` with `scroll-pt-9` here, or
   * focusing a row control just above the fold scrolls it under the pinned
   * header. Leave the container's top padding at zero: a sticky inset
   * resolves against the padding box.
   */
  containerClassName?: string
  /**
   * Names the scroll container for assistive tech. Applied only while the
   * table overflows and the container is therefore focusable; without it the
   * region is still roled but stays unnamed, which keeps a page of tables
   * from becoming a set of identically-named landmarks. Supply it whenever
   * the table can overflow.
   */
  containerLabel?: string
}

/**
 * The table element inside a scroll container. Establishes the table's
 * compact type scale; renders standalone as a plain table, or inside a
 * `TableShell` for the full panel chrome.
 *
 * Cells default to `whitespace-nowrap`, so wide tables scroll rather than
 * wrap. While the table actually overflows — on either axis, including a
 * height capped through `containerClassName` — the container becomes
 * keyboard focusable so the off-screen rows and columns stay reachable
 * without a pointer, and draws an inset focus outline the shell's clipped
 * corners cannot swallow.
 */
function Table({
  className,
  containerClassName,
  containerLabel,
  ...props
}: TableProps) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const [overflows, setOverflows] = React.useState(false)

  // Only an overflowing region needs a tab stop; adding one to every table
  // would put a focus stop on nothing.
  React.useEffect(() => {
    const element = containerRef.current
    if (!element) return
    // Both axes: a host that caps the height with `containerClassName`
    // scrolls vertically even when every column fits, and that region needs
    // the same keyboard reachability.
    const measure = () =>
      setOverflows(
        element.scrollWidth > element.clientWidth + 1 ||
          element.scrollHeight > element.clientHeight + 1,
      )
    // Measure once regardless, so the initial layout is still handled where
    // ResizeObserver is unavailable.
    measure()
    if (typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    const table = element.firstElementChild
    if (table) observer.observe(table)
    return () => observer.disconnect()
  }, [])

  return (
    <div
      data-slot="table-scroll-frame"
      // The flex column with min-h-0 on frame and container gives the scroll
      // container a real height path: when an ancestor (a TableShell inside a
      // height-capped host, say) constrains the frame, the container shrinks
      // with it and scrolls, instead of percentage caps resolving against an
      // auto-height frame and silently clipping. Auto-height usages lay out
      // exactly as before.
      className="relative flex min-h-0 w-full min-w-0 flex-col"
    >
      <div
        ref={containerRef}
        data-slot="table-container"
        // `region` — not `group` — is the role axe accepts on a focusable
        // scroll container. The name is only applied when the host supplies
        // one: an unnamed region is not a landmark, which keeps every table
        // on a page from becoming an identically-named landmark.
        role={overflows ? "region" : undefined}
        aria-label={overflows ? containerLabel : undefined}
        // Stays programmatically focusable when the overflow goes away, so a
        // container that is focused when the table shrinks keeps its focus
        // instead of dropping it to the document body. The cost is that a
        // pointer click on cell text focuses the container rather than the
        // body; `:focus-visible` does not match that, so nothing is drawn.
        tabIndex={overflows ? 0 : -1}
        className={cn(
          // `overflow-y` is deliberately left unset: CSS coerces it to `auto`
          // beside `overflow-x-auto`, which is what lets a host cap the
          // height through `containerClassName` and get a scrolling body.
          // Setting it explicitly to `visible` or `hidden` would clip rows.
          "peer min-h-0 w-full min-w-0 overflow-x-auto outline-none focus-visible:[outline-style:solid] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring",
          tableScrollbarClassName,
          containerClassName,
        )}
      >
        <table
          data-slot="table"
          className={cn("w-full caption-bottom font-sans nessa-text-2", className)}
          {...props}
        />
      </div>
      {/* A sticky header cell is an opaque positioned descendant, so it
          paints over the container's own outline and erases the ring's top
          and side segments. This overlay is a later sibling at a higher
          layer, so it draws the same ring above the pinned cells; the two
          share a box and coincide as one. */}
      <div
        aria-hidden="true"
        data-slot="table-focus-ring"
        className="pointer-events-none absolute inset-0 z-20 hidden outline-2 [outline-style:solid] -outline-offset-2 outline-ring peer-focus-visible:block"
      />
    </div>
  )
}

export interface TableHeaderProps extends React.ComponentProps<"thead"> {
  /**
   * Pins the header cells to the top of the scroll container while the body
   * scrolls beneath them — for a table whose height is capped through
   * `Table`'s `containerClassName`.
   *
   * The cells take the card surface so rows cannot show through, and draw
   * their own bottom rule as a shadow: tables collapse their borders, so a
   * sticky cell's border belongs to the collapsed grid and scrolls away with
   * the rows. (MUI instead switches the table to `border-collapse: separate`;
   * that is not open to us, because the separated model ignores borders on
   * `tr` and every row rule in this kit lives there.)
   *
   * The vertical scrollbar belongs to the scroll port, so it runs alongside
   * the pinned header too. That is the same behaviour as MUI's `stickyHeader`
   * and every shadcn sticky-table recipe: the alternative — a separate header
   * table above a scrolling body — severs the programmatic link between each
   * `columnheader` and its cells, and buys a permanent column-width
   * synchronisation problem. The seam is cosmetic and, on platforms with
   * overlay scrollbars, usually invisible.
   *
   * Assumes a single header row — every cell pins at the same offset, so a
   * two-tier grouped header would stack both rows on top of each other — and
   * a scroll container with no top padding, since a sticky inset resolves
   * against the padding box and rows would scroll through the gap above.
   *
   * The surface only applies to cells that set none of their own, so a
   * `TableHead` with a `bg-*` class keeps it. To restyle every cell, pass the
   * same descendant form here: `className="[&_th]:bg-popover"` — a bare
   * `bg-*` would land on the `thead` and the opaque cells would cover it.
   */
  sticky?: boolean
}

/**
 * The column-header row group of a `Table`, optionally pinned to the top of
 * a capped-height scroll container.
 */
function TableHeader({ className, sticky = false, ...props }: TableHeaderProps) {
  return (
    <thead
      data-slot="table-header"
      // Styling and test hook for hosts that need to target the pinned state.
      data-sticky={sticky || undefined}
      className={cn(
        sticky &&
          "[&_th]:sticky [&_th]:top-0 [&_th]:z-10 [&_th:not([class*='bg-'])]:bg-card [&_th]:shadow-[inset_0_-1px_0_var(--color-border)]",
        className,
      )}
      {...props}
    />
  )
}

/**
 * The data row group of a `Table`. Drops the final row's rule so the shell
 * border closes the panel.
 */
function TableBody({ className, ...props }: React.ComponentProps<"tbody">) {
  return (
    <tbody
      data-slot="table-body"
      className={cn("[&_tr:last-child]:border-0", className)}
      {...props}
    />
  )
}

/** A summary row group rendered on the muted wash beneath the data rows. */
function TableFooter({ className, ...props }: React.ComponentProps<"tfoot">) {
  return (
    <tfoot
      data-slot="table-footer"
      className={cn(
        "border-t border-border bg-muted/50 font-medium [&>tr]:last:border-b-0",
        className,
      )}
      {...props}
    />
  )
}

/**
 * One table row: a hairline rule above its successor, a muted hover wash,
 * and a stronger wash while `data-state="selected"`.
 */
function TableRow({ className, ...props }: React.ComponentProps<"tr">) {
  return (
    <tr
      data-slot="table-row"
      className={cn(
        "border-b border-border transition-colors [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] hover:bg-muted/50 data-[state=selected]:bg-muted motion-reduce:transition-none",
        className,
      )}
      {...props}
    />
  )
}

/**
 * A column-header cell: small semibold muted type in sentence case. When the
 * column is sorted, set `aria-sort` here and render a `TableSortButton` as
 * the cell content.
 */
function TableHead({ className, ...props }: React.ComponentProps<"th">) {
  return (
    <th
      data-slot="table-head"
      className={cn(
        "h-9 whitespace-nowrap px-3 text-left align-middle nessa-text-1 font-semibold text-muted-foreground",
        className,
      )}
      {...props}
    />
  )
}

/** One data cell. Numeric or temporal cells add `font-mono` themselves. */
function TableCell({ className, ...props }: React.ComponentProps<"td">) {
  return (
    <td
      data-slot="table-cell"
      className={cn("whitespace-nowrap px-3 py-2.5 align-middle", className)}
      {...props}
    />
  )
}

/** The table's caption, rendered under the rows in muted type. */
function TableCaption({
  className,
  ...props
}: React.ComponentProps<"caption">) {
  return (
    <caption
      data-slot="table-caption"
      className={cn("my-3 px-3 nessa-text-2 text-muted-foreground", className)}
      {...props}
    />
  )
}

export interface TableEmptyProps extends React.ComponentProps<"td"> {
  /**
   * Columns the empty state spans. Must equal the number of headers the
   * table currently renders — with toggleable columns, derive it from the
   * visible set rather than hardcoding, or table navigation reports a
   * column count that does not match the header row.
   */
  colSpan: number
}

/**
 * The row a table shows instead of data: a full-width, vertically centered
 * region for an icon, title, and hint. Renders as a single row spanning
 * `colSpan` columns.
 *
 * Deliberately not a live region: it mounts with its content already in
 * place, which several screen readers skip, and it would double up with the
 * host's result summary. Keep one status region — that summary, whether it
 * is `TablePagination`'s or the host's own — for "what the filter did".
 */
function TableEmpty({ colSpan, className, children, ...props }: TableEmptyProps) {
  return (
    <tr data-slot="table-empty">
      <td
        colSpan={colSpan}
        className={cn("h-45 px-6 text-center align-middle", className)}
        {...props}
      >
        <div className="inline-flex flex-col items-center gap-1 whitespace-normal text-muted-foreground">
          {children}
        </div>
      </td>
    </tr>
  )
}

/** A column's sort direction, matching the `aria-sort` token set. */
export type TableSortDirection = "ascending" | "descending"

export interface TableSortButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * The column's current sort direction; omit while unsorted. Mirror the
   * value onto the surrounding `TableHead`'s `aria-sort`.
   */
  direction?: TableSortDirection
}

/**
 * The clickable label of a sortable column header. Shows the sort direction
 * beside the label, or a neutral both-ways glyph while the column is
 * unsorted, and toggles on click — the host owns the cycle, so it can flip
 * between the two directions or add an unsorted step of its own.
 *
 * Column visibility belongs in the toolbar's `TableViewOptions`, not here:
 * a per-header menu for two mutually exclusive directions is more chrome
 * than a toggle needs.
 */
function TableSortButton({
  direction,
  className,
  children,
  ...props
}: TableSortButtonProps) {
  const DirectionIcon =
    direction === "ascending"
      ? ArrowUp
      : direction === "descending"
        ? ArrowDown
        : ChevronsUpDown
  return (
    <button
      type="button"
      data-slot="table-sort-button"
      data-direction={direction}
      className={cn(
        "-mx-1.5 inline-flex cursor-pointer appearance-none items-center gap-1 rounded-md border-0 bg-transparent px-1.5 py-1 font-sans nessa-text-1 font-semibold text-muted-foreground outline-none transition-colors [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] hover:bg-accent hover:text-accent-foreground focus-visible:[outline-style:solid] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none",
        className,
      )}
      {...props}
    >
      {children}
      {/* The unsorted glyph is the only cue that a plain-looking header is
          sortable, so it stays at full strength for the 3:1 non-text
          contrast floor. */}
      <DirectionIcon aria-hidden="true" className="size-3 shrink-0" />
    </button>
  )
}

export {
  Table,
  TableBody,
  TableCaption,
  TableCell,
  TableEmpty,
  TableFooter,
  TableHead,
  TableHeader,
  TableRow,
  TableShell,
  TableSortButton,
  tableScrollbarClassName,
}

"use client"

import * as React from "react"
import { cva } from "class-variance-authority"
import { ChevronDown, Columns3, ListFilter, Search } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "../badge"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "../dropdown-menu"
import { Input } from "../input"

/**
 * The shared recipe for the toolbar's buttons: one height, one radius, one
 * hover and focus treatment across the filter disclosure, the facet selects,
 * and the column menu, so a toolbar row reads as a set. Exported like
 * `buttonVariants` so a host can build a matching control.
 *
 * `TableSearchField` is deliberately not on this recipe — it is an `Input`,
 * and keeps that component's own field focus treatment; only its height is
 * matched here.
 */
const tableControlVariants = cva(
  "inline-flex h-8 box-border shrink-0 cursor-pointer appearance-none items-center gap-2 whitespace-nowrap rounded-md border border-input bg-transparent font-sans nessa-text-2 font-medium text-foreground outline-none transition-[color,background-color,border-color] [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] hover:bg-accent hover:text-accent-foreground focus-visible:[outline-style:solid] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 aria-expanded:border-ring motion-reduce:transition-none",
  {
    variants: {
      padding: {
        default: "px-3",
        tight: "min-w-0 px-2.5",
      },
      state: {
        none: "",
        active:
          "data-[active=true]:border-ring data-[active=true]:bg-accent data-[active=true]:text-accent-foreground",
      },
    },
    defaultVariants: { padding: "default", state: "none" },
  },
)

/**
 * The primary filter row above a table shell: a search field, filter
 * controls, and — pushed right with `ml-auto` — an optional summary. Wraps
 * on narrow hosts.
 */
function TableToolbar({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="table-toolbar"
      className={cn(
        "flex w-full min-w-0 flex-wrap items-center gap-2 font-sans",
        className,
      )}
      {...props}
    />
  )
}

/**
 * The disclosed advanced-filter row a `TableFilterToggle` opens: a bordered
 * card strip holding the secondary filter controls. The host renders it
 * conditionally beneath the toolbar, and should give it an `id` matching the
 * toggle's `aria-controls`.
 */
function TableFilterPanel({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="table-filter-panel"
      className={cn(
        "flex w-full min-w-0 flex-wrap items-center gap-2 rounded-xl border border-border bg-card p-3 font-sans",
        className,
      )}
      {...props}
    />
  )
}

export interface TableSearchFieldProps extends React.ComponentProps<"input"> {
  /**
   * Extends the inner input element; `className` extends the field wrapper,
   * e.g. to change its flex basis.
   */
  inputClassName?: string
}

/**
 * The toolbar's free-text search: a compact `Input` with a leading search
 * glyph. Give it an accessible name via `aria-label` or an external label.
 */
function TableSearchField({
  className,
  inputClassName,
  type = "search",
  ...props
}: TableSearchFieldProps) {
  return (
    <div
      data-slot="table-search-field"
      className={cn("relative min-w-55 flex-[1_1_17.5rem]", className)}
    >
      <Search
        aria-hidden="true"
        className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground"
      />
      <Input
        type={type}
        className={cn("h-8 pl-8 nessa-text-input-2", inputClassName)}
        {...props}
      />
    </div>
  )
}

export interface TableFilterToggleProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onSelect"> {
  /** Whether the advanced-filter panel is disclosed; drives `aria-expanded`. */
  open?: boolean
  /**
   * Advanced filters currently active — search excluded. Non-zero renders
   * the count beside the label and tints the control active.
   */
  activeCount?: number
  /** Replaces the default "Filters" label. */
  children?: React.ReactNode
}

/**
 * The disclosure button for a `TableFilterPanel`: a "Filters" control that
 * carries the active-filter count and flips its chevron while open. State
 * stays with the host; wire `onClick` to toggle `open`, and pass
 * `aria-controls` naming the panel it discloses. A panel rendered only
 * while open leaves that reference dangling when collapsed — keep the panel
 * mounted and hidden if your audit requires the id to always resolve.
 */
function TableFilterToggle({
  open = false,
  activeCount = 0,
  className,
  children,
  ...props
}: TableFilterToggleProps) {
  return (
    <button
      type="button"
      data-slot="table-filter-toggle"
      data-active={activeCount > 0}
      aria-expanded={open}
      className={cn(tableControlVariants({ state: "active" }), className)}
      {...props}
    >
      <ListFilter aria-hidden="true" className="size-3.5 shrink-0" />
      {children ?? "Filters"}
      {activeCount > 0 ? (
        <Badge variant="secondary" className="px-1.5 font-mono nessa-text-1 tabular-nums">
          {activeCount}
        </Badge>
      ) : null}
      <ChevronDown
        aria-hidden="true"
        className={cn(
          "size-3.5 shrink-0 transition-transform [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
          open && "rotate-180",
        )}
      />
    </button>
  )
}

export interface TableFilterOption {
  /** Value reported through `onValueChange` when this option is chosen. */
  value: string
  /** Option text in the menu, and the trigger's label while selected. */
  label: React.ReactNode
  /** Faceted result count shown right-aligned beside the option. */
  count?: number
}

export interface TableFilterSelectProps
  extends Omit<
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    "value" | "defaultValue" | "onChange" | "onSelect" | "children"
  > {
  /** The facet's name: the menu heading and the trigger's spoken prefix. */
  label: string
  /** The selectable options, in menu order. */
  options: readonly TableFilterOption[]
  /** Selected option value; supply with `onValueChange` to control it. */
  value?: string
  /** Initial selection while uncontrolled. */
  defaultValue?: string
  /** Receives the chosen option's value. */
  onValueChange?: (value: string) => void
  /** Extends the floating menu surface. */
  contentClassName?: string
  /** Portal container for the floating menu; defaults to the body. */
  portalContainer?: HTMLElement | null
}

/**
 * One faceted filter: a compact trigger showing the selected option that
 * opens a single-select menu with optional per-option counts. Controlled via
 * `value`/`onValueChange`, or uncontrolled from `defaultValue`.
 *
 * When the held value names no current option — before an async `options`
 * set arrives, say — the trigger shows the facet name alone rather than
 * standing in a different option: displaying a selection the host was never
 * told about would leave the two disagreeing about what is filtered.
 */
function TableFilterSelect({
  label,
  options,
  value: valueProp,
  defaultValue,
  onValueChange,
  contentClassName,
  portalContainer,
  className,
  ...props
}: TableFilterSelectProps) {
  const [uncontrolledValue, setUncontrolledValue] = React.useState<string>(
    defaultValue ?? "",
  )
  const value = valueProp ?? uncontrolledValue
  const current = options.find((option) => option.value === value)

  const setValue = React.useCallback(
    (nextValue: string) => {
      if (valueProp === undefined) setUncontrolledValue(nextValue)
      onValueChange?.(nextValue)
    },
    [onValueChange, valueProp],
  )

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button
          type="button"
          data-slot="table-filter-select"
          className={cn(tableControlVariants({ padding: "tight" }), className)}
          {...props}
        >
          {/* The visible text is the selected option, so the facet name is
              voiced as a prefix rather than replacing it — an aria-label
              alone would leave the visible words unspeakable. */}
          {current ? <span className="sr-only">{label} </span> : null}
          <span className="truncate">{current?.label ?? label}</span>
          <ChevronDown aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        data-slot="table-filter-select-content"
        align="start"
        portalContainer={portalContainer}
        className={cn("min-w-44", contentClassName)}
      >
        <DropdownMenuLabel>{label}</DropdownMenuLabel>
        <DropdownMenuRadioGroup value={value} onValueChange={setValue}>
          {options.map((option) => (
            <DropdownMenuRadioItem
              key={option.value}
              value={option.value}
              className="nessa-text-2"
            >
              <span className="flex-1 truncate">{option.label}</span>
              {option.count !== undefined ? (
                <span className="font-mono nessa-text-1 tabular-nums text-muted-foreground">
                  {option.count}
                </span>
              ) : null}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

export interface TableViewColumn {
  /** Stable column key the host uses to track visibility. */
  id: string
  /** Entry text in the menu; usually the column's header label. */
  label: React.ReactNode
  /**
   * Locks the column visible: its entry renders disabled. Keep the id in
   * `value` as well, or the entry renders unchecked and unreachable.
   */
  locked?: boolean
}

export interface TableViewOptionsProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onSelect"> {
  /** Every toggleable column, in menu order. */
  columns: readonly TableViewColumn[]
  /** Ids of the currently visible columns. */
  value: readonly string[]
  /** Receives the next visible-id list. */
  onValueChange?: (value: string[]) => void
  /** Extends the floating menu surface. */
  contentClassName?: string
  /** Portal container for the floating menu; defaults to the body. */
  portalContainer?: HTMLElement | null
  /** Replaces the default "Columns" label. */
  children?: React.ReactNode
  /**
   * Forwarded to the trigger button — a focus destination for a host that
   * hides a column from somewhere that unmounts on the same interaction.
   */
  ref?: React.Ref<HTMLButtonElement>
}

/**
 * The toolbar's column-visibility menu: a "Columns" trigger over one
 * checkbox entry per column. Fully controlled — `value` lists the visible
 * column ids and `onValueChange` receives the next list. The caller's
 * existing order is kept and a restored column is slotted back among its
 * `columns` neighbours, so ids that `columns` does not describe — a fixed
 * selection or actions column — never shift position.
 */
function TableViewOptions({
  columns,
  value,
  onValueChange,
  contentClassName,
  portalContainer,
  className,
  children,
  ref,
  ...props
}: TableViewOptionsProps) {
  const toggle = (id: string, next: boolean) => {
    if (!next) {
      onValueChange?.(value.filter((entry) => entry !== id))
      return
    }
    if (value.includes(id)) return
    // Slot the restored column back among its known neighbours instead of
    // appending it, and leave every other entry — including ids `columns`
    // does not describe, such as a fixed selection column — where it was.
    const order = columns.map((column) => column.id)
    const position = order.indexOf(id)
    const nextValue = [...value]
    const insertAt = nextValue.findIndex((entry) => {
      const entryPosition = order.indexOf(entry)
      return entryPosition !== -1 && entryPosition > position
    })
    nextValue.splice(insertAt === -1 ? nextValue.length : insertAt, 0, id)
    onValueChange?.(nextValue)
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button
          ref={ref}
          type="button"
          data-slot="table-view-options"
          className={cn(tableControlVariants(), className)}
          {...props}
        >
          <Columns3 aria-hidden="true" className="size-3.5 shrink-0" />
          {children ?? "Columns"}
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        data-slot="table-view-options-content"
        align="end"
        portalContainer={portalContainer}
        className={cn("min-w-44", contentClassName)}
      >
        <DropdownMenuLabel>Toggle columns</DropdownMenuLabel>
        {columns.map((column) => (
          <DropdownMenuCheckboxItem
            key={column.id}
            checked={value.includes(column.id)}
            disabled={column.locked}
            onCheckedChange={(next) => toggle(column.id, next === true)}
            onSelect={(event) => event.preventDefault()}
            className="nessa-text-2"
          >
            {column.label}
          </DropdownMenuCheckboxItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

export {
  TableFilterPanel,
  TableFilterSelect,
  TableFilterToggle,
  TableSearchField,
  TableToolbar,
  TableViewOptions,
  tableControlVariants,
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  Pagination,
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
} from "../pagination"

/**
 * Computes the page items a pagination bar shows for `page` of `pageCount`:
 * every page when seven or fewer fit, otherwise a seven-slot window keeping
 * the first page, the last page, and the current page's neighbors, with
 * `"ellipsis"` marking each collapsed run. `page` is clamped into range.
 */
function tablePaginationRange(
  page: number,
  pageCount: number,
): (number | "ellipsis")[] {
  if (pageCount <= 7) {
    return Array.from({ length: Math.max(pageCount, 0) }, (_, index) => index + 1)
  }
  const current = Math.min(Math.max(page, 1), pageCount)
  if (current <= 4) return [1, 2, 3, 4, 5, "ellipsis", pageCount]
  if (current >= pageCount - 3) {
    return [
      1,
      "ellipsis",
      pageCount - 4,
      pageCount - 3,
      pageCount - 2,
      pageCount - 1,
      pageCount,
    ]
  }
  return [1, "ellipsis", current - 1, current, current + 1, "ellipsis", pageCount]
}

// The table pager is a dense strip inside the shell, so its edge controls
// collapse to the chevron alone. They keep `PaginationPrevious`/`Next`'s
// accessible names, so the control is still announced in full.
const paginationEdgeClassName = "w-7 px-0 [&>span]:hidden"

export interface TablePaginationProps
  extends Omit<React.ComponentProps<"div">, "onChange"> {
  /** The current page, 1-based. Clamped into range for every control. */
  page: number
  /** Total pages; `0` renders the pager with no numbered buttons. */
  pageCount: number
  /** Receives the requested page, already clamped into range. */
  onPageChange?: (page: number) => void
  /**
   * Left-aligned result summary, e.g. "Showing 1–12 of 47 traces". Rendered
   * as a status region, so a host feeding it from a live-typing search
   * should debounce the value rather than announcing every keystroke.
   */
  summary?: React.ReactNode
  /** Accessible name of the pagination landmark. */
  paginationLabel?: string
}

/**
 * The pager row under a table's rows, inside the shell: a muted result
 * summary on the left and, composed from the Pagination primitives, compact
 * previous/next controls around a windowed set of numbered page buttons.
 * Fully controlled — the host owns `page` and re-renders on `onPageChange`.
 *
 * `page` is clamped into `[1, pageCount]` for every control, so a page that
 * falls out of range — a filter shrinking the result set before the host
 * resets it — still highlights a real page and cannot step further out. The
 * summary is a status region, so filtering and paging are announced rather
 * than changing silently.
 */
function TablePagination({
  page,
  pageCount,
  onPageChange,
  summary,
  paginationLabel = "Pagination",
  className,
  ...props
}: TablePaginationProps) {
  const safePageCount = Number.isFinite(pageCount)
    ? Math.max(0, Math.floor(pageCount))
    : 0
  const requested = Number.isFinite(page) ? Math.floor(page) : 1
  const currentPage =
    safePageCount === 0 ? 1 : Math.min(Math.max(requested, 1), safePageCount)
  const items = tablePaginationRange(currentPage, safePageCount)

  return (
    <div
      data-slot="table-pagination"
      className={cn(
        "flex box-border min-h-9.5 w-full items-center justify-between gap-2 border-t border-border px-2.5 py-1.5 font-sans",
        className,
      )}
      {...props}
    >
      <div
        role="status"
        className="min-w-0 truncate nessa-text-1 text-muted-foreground"
      >
        {summary}
      </div>
      <Pagination aria-label={paginationLabel} className="mx-0 w-auto shrink-0">
        <PaginationContent>
          <PaginationItem>
            <PaginationPrevious
              className={paginationEdgeClassName}
              disabled={currentPage <= 1}
              onClick={() => onPageChange?.(currentPage - 1)}
            />
          </PaginationItem>
          {items.map((item, index) => (
            <PaginationItem key={item === "ellipsis" ? `ellipsis-${index}` : item}>
              {item === "ellipsis" ? (
                <PaginationEllipsis />
              ) : (
                <PaginationLink
                  aria-label={`Page ${item}`}
                  isActive={item === currentPage}
                  onClick={() => onPageChange?.(item)}
                >
                  {item}
                </PaginationLink>
              )}
            </PaginationItem>
          ))}
          <PaginationItem>
            <PaginationNext
              className={paginationEdgeClassName}
              disabled={currentPage >= safePageCount}
              onClick={() => onPageChange?.(currentPage + 1)}
            />
          </PaginationItem>
        </PaginationContent>
      </Pagination>
    </div>
  )
}

export { TablePagination, tablePaginationRange }
